import{_ as e,o as l,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Want to Become a Ceph Ambassador? - Gaurav Sitlani, IBM","description":"","frontmatter":{"title":"Want to Become a Ceph Ambassador? - Gaurav Sitlani, IBM","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph社区","分布式存储","Ceph大使","开源项目","用户增长"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Want_to_Become_a_Ceph_Ambassador_-_Gaurav_Sitlani_IBM.md","filePath":"posts/2025/Want_to_Become_a_Ceph_Ambassador_-_Gaurav_Sitlani_IBM.md","lastUpdated":1780459816000}'),o={name:"posts/2025/Want_to_Become_a_Ceph_Ambassador_-_Gaurav_Sitlani_IBM.md"};function r(s,a,_,n,p,h){return l(),t("div",null,[...a[0]||(a[0]=[i('<p>Ceph作为一个分布式存储系统，在存储领域扮演着重要角色。在由Gaurav Sitlani主持的会议中，SEF Ambassador项目得到了详细介绍，该项目旨在表彰和鼓励在Ceph社区中积极参与的个体。以下是会议的关键点：</p><h3 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h3><p>Gaurav Sitlani介绍了SEF Ambassador项目，这个项目由Mike Perez发起，目的是通过社区大使推动Ceph在全球范围内的扩展和增长。</p><h3 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h3><ol><li><p><strong>SEF Ambassador项目介绍</strong></p><ul><li>项目目标是通过大使们的努力，吸引新用户加入Ceph项目，提升用户体验，并收集来自不同地区的反馈以改进项目。</li><li>当前进展：大使们已在多个国家和地区活跃，包括印度、美国、英国、法国、德国、荷兰、韩国、中国等，组织了多次用户研讨会、开发者会议等活动。</li></ul></li><li><p><strong>社区扩展计划</strong></p><ul><li>全球扩展：计划在拉丁美洲、亚太地区、欧洲等地区招募更多大使，确保每个地区至少有三名大使。</li><li>活动与合作：大使们将参与组织活动、寻找赞助、收集用户反馈，并与研究机构、企业和开源项目合作。</li></ul></li><li><p><strong>大使的角色与职责</strong></p><ul><li>社区支持：通过组织活动、提供技术支持、撰写文档等方式，帮助新用户融入社区。</li><li>反馈收集：定期收集用户反馈，参与用户委员会和开发者会议，帮助改进Ceph项目。</li></ul></li><li><p><strong>未来计划</strong></p><ul><li>新贡献者招募：计划招募更多开发者、研究人员和学生参与Ceph项目。</li><li>社区增长：通过大使们的努力，推动Ceph在 全球范围内的社区增长，特别是在新兴市场和技术领域。</li></ul></li></ol><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li>招募新大使：计划在拉丁美洲、亚太地区、欧洲等地区招募更多大使。</li><li>社区扩展：继续通过大使们的努力，推动Ceph在全球范围内的社区扩展。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>招募新大使：鼓励对Ceph社区感兴趣的个人加入Ambassador项目。</li><li>反馈收集：大使们将继续收集用户反馈，参与用户委员会和开发者会议。</li><li>活动组织：大使们将组织更多活动，包括用户研讨会、黑客松等。</li></ul><h3 id="会议总结" tabindex="-1">会议总结 <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结&quot;">​</a></h3><p>SEF Ambassador项目通过全球大使的努力，成功推动了Ceph社区的扩展与成长。未来，项目将继续在更多地区招募大使，并通过组织活动、收集反馈等方式，进一步提升Ceph的用户体验和社区影响力。</p>',11)])])}const m=e(o,[["render",r]]);export{u as __pageData,m as default};
